    "data"    => fopen("data://text/plain,hello", "r"),
    "file"    => fopen(tempnam(sys_get_temp_dir(), "fl"), "w+"),
];

foreach ($cases as $name => $handle) {
    echo $name, " ex=", var_export(flock($handle, LOCK_EX), true);
    echo " sh=", var_export(flock($handle, LOCK_SH), true);
    echo " nb=", var_export(flock($handle, LOCK_EX | LOCK_NB), true);
    echo " un=", var_export(flock($handle, LOCK_UN), true), "\n";
